{
  "$schema": "https://json-schema.org/draft/2020-12/schema",
  "$id": "urn:umf:core:dataset-value-compact-operation:1.0.0",
  "title": "Experimental compact supplied dataset value receipt",
  "type": "object",
  "properties": {
    "operation": {
      "const": "validate-core-dataset-values-compact"
    },
    "version": {
      "const": "1.0.0"
    },
    "scope": {
      "const": "supplied-dataset-only"
    },
    "provenance": {
      "const": "unverified"
    },
    "source": {
      "$ref": "urn:umf:core:0.8.0"
    },
    "input": {
      "$ref": "#/$defs/input"
    },
    "documentValidation": {
      "$ref": "#/$defs/validation"
    },
    "records": {
      "type": "array",
      "items": {
        "type": "object",
        "properties": {
          "instanceId": {
            "type": "string",
            "minLength": 1
          },
          "result": {
            "$ref": "#/$defs/recordCheck"
          }
        },
        "required": [
          "instanceId",
          "result"
        ],
        "additionalProperties": false
      }
    },
    "keys": {
      "type": "array",
      "items": {
        "type": "object",
        "properties": {
          "instanceId": {
            "type": "string",
            "minLength": 1
          },
          "result": {
            "$ref": "#/$defs/compactKey"
          }
        },
        "required": [
          "instanceId",
          "result"
        ],
        "additionalProperties": false
      }
    },
    "relationships": {
      "type": "array",
      "items": {
        "type": "object",
        "properties": {
          "instanceId": {
            "type": "string",
            "minLength": 1
          },
          "identity": {
            "$ref": "#/$defs/relationshipIdentity"
          },
          "sourceInstanceId": {
            "type": "string",
            "minLength": 1
          },
          "targetInstanceId": {
            "type": "string",
            "minLength": 1
          },
          "targetKey": {
            "$ref": "#/$defs/compactKey"
          }
        },
        "required": [
          "instanceId",
          "identity",
          "sourceInstanceId",
          "targetInstanceId",
          "targetKey"
        ],
        "additionalProperties": false
      }
    },
    "datasetValidation": {
      "$ref": "#/$defs/validation"
    },
    "obligations": {
      "type": "array",
      "items": {
        "type": "object",
        "properties": {
          "id": {
            "enum": [
              "dataset.keys",
              "dataset.relationships"
            ]
          },
          "state": {
            "enum": [
              "satisfied",
              "invalid",
              "unresolved"
            ]
          },
          "scope": {
            "const": "supplied-dataset-only"
          }
        },
        "required": [
          "id",
          "state",
          "scope"
        ],
        "additionalProperties": false
      }
    },
    "residuals": {
      "type": "array",
      "items": {
        "type": "object",
        "properties": {
          "path": {
            "type": "string"
          },
          "value": {},
          "reason": {
            "type": "string",
            "minLength": 1
          }
        },
        "required": [
          "path",
          "value",
          "reason"
        ],
        "additionalProperties": false
      }
    }
  },
  "required": [
    "operation",
    "version",
    "scope",
    "provenance",
    "source",
    "input",
    "documentValidation",
    "records",
    "keys",
    "relationships",
    "datasetValidation",
    "obligations",
    "residuals"
  ],
  "additionalProperties": false,
  "$defs": {
    "identity": {
      "type": "object",
      "properties": {
        "module": {
          "type": "string",
          "minLength": 1
        },
        "element": {
          "type": "string",
          "minLength": 1
        }
      },
      "required": [
        "module",
        "element"
      ],
      "additionalProperties": false
    },
    "relationshipIdentity": {
      "type": "object",
      "properties": {
        "module": {
          "type": "string",
          "minLength": 1
        },
        "id": {
          "type": "string",
          "minLength": 1
        }
      },
      "required": [
        "module",
        "id"
      ],
      "additionalProperties": false
    },
    "validation": {
      "type": "object",
      "properties": {
        "valid": {
          "type": "boolean"
        },
        "complete": {
          "type": "boolean"
        },
        "diagnostics": {
          "type": "array",
          "items": {
            "type": "object",
            "properties": {
              "code": {
                "type": "string",
                "minLength": 1
              },
              "path": {
                "type": "string"
              },
              "message": {
                "type": "string"
              },
              "severity": {
                "enum": [
                  "error",
                  "warning"
                ]
              }
            },
            "required": [
              "code",
              "path",
              "message",
              "severity"
            ],
            "additionalProperties": false
          }
        }
      },
      "required": [
        "valid",
        "complete",
        "diagnostics"
      ],
      "additionalProperties": false
    },
    "fieldValue": {
      "oneOf": [
        {
          "type": "object",
          "properties": {
            "field": {
              "$ref": "#/$defs/identity"
            },
            "state": {
              "const": "absent"
            }
          },
          "required": [
            "field",
            "state"
          ],
          "additionalProperties": false
        },
        {
          "type": "object",
          "properties": {
            "field": {
              "$ref": "#/$defs/identity"
            },
            "state": {
              "const": "present"
            },
            "value": {
              "$ref": "urn:umf:core:0.8.0#/$defs/literal"
            }
          },
          "required": [
            "field",
            "state",
            "value"
          ],
          "additionalProperties": false
        }
      ]
    },
    "input": {
      "type": "object",
      "properties": {
        "scope": {
          "type": "object",
          "properties": {
            "id": {
              "type": "string",
              "minLength": 1
            },
            "closure": {
              "const": "supplied-dataset-only"
            }
          },
          "required": [
            "id",
            "closure"
          ],
          "additionalProperties": false
        },
        "records": {
          "type": "array",
          "items": {
            "type": "object",
            "properties": {
              "instanceId": {
                "type": "string",
                "minLength": 1
              },
              "identity": {
                "$ref": "#/$defs/identity"
              },
              "values": {
                "type": "array",
                "items": {
                  "$ref": "#/$defs/fieldValue"
                }
              }
            },
            "required": [
              "instanceId",
              "identity",
              "values"
            ],
            "additionalProperties": false
          },
          "maxItems": 1000
        },
        "relationships": {
          "type": "array",
          "items": {
            "type": "object",
            "properties": {
              "instanceId": {
                "type": "string",
                "minLength": 1
              },
              "identity": {
                "$ref": "#/$defs/relationshipIdentity"
              },
              "sourceInstanceId": {
                "type": "string",
                "minLength": 1
              },
              "target": {
                "type": "object",
                "properties": {
                  "identity": {
                    "$ref": "urn:umf:core:key-tuple-operation:3.0.0#/$defs/identity"
                  },
                  "values": {
                    "type": "array",
                    "items": {
                      "$ref": "urn:umf:core:key-tuple-operation:3.0.0#/$defs/value"
                    }
                  }
                },
                "required": [
                  "identity",
                  "values"
                ],
                "additionalProperties": false
              }
            },
            "required": [
              "instanceId",
              "identity",
              "sourceInstanceId",
              "target"
            ],
            "additionalProperties": false
          },
          "maxItems": 10000
        },
        "context": {}
      },
      "required": [
        "scope",
        "records",
        "relationships"
      ],
      "additionalProperties": false
    },
    "recordCheck": {
      "type": "object",
      "properties": {
        "operation": {
          "const": "validate-core-record-values"
        },
        "version": {
          "const": "1.0.0"
        },
        "identity": {
          "$ref": "#/$defs/identity"
        },
        "values": {
          "type": "array",
          "items": {
            "$ref": "#/$defs/fieldValue"
          }
        },
        "documentValidation": {
          "$ref": "#/$defs/validation"
        },
        "validation": {
          "$ref": "#/$defs/validation"
        },
        "fields": {
          "type": "array",
          "items": {
            "type": "object",
            "properties": {
              "field": {
                "$ref": "#/$defs/identity"
              },
              "state": {
                "enum": [
                  "absent",
                  "present"
                ]
              },
              "validation": {
                "$ref": "#/$defs/validation"
              }
            },
            "required": [
              "field",
              "state",
              "validation"
            ],
            "additionalProperties": false
          }
        },
        "sourceRef": {
          "const": "#/source"
        }
      },
      "required": [
        "operation",
        "version",
        "sourceRef",
        "identity",
        "values",
        "documentValidation",
        "validation",
        "fields"
      ],
      "additionalProperties": false
    },
    "keyIdentity": {
      "type": "object",
      "required": [
        "module",
        "element",
        "key"
      ],
      "additionalProperties": false,
      "properties": {
        "module": {
          "type": "string",
          "minLength": 1
        },
        "element": {
          "type": "string",
          "minLength": 1
        },
        "key": {
          "type": "string",
          "minLength": 1
        }
      }
    },
    "keyValue": {
      "oneOf": [
        {
          "type": "object",
          "required": [
            "boolean"
          ],
          "additionalProperties": false,
          "properties": {
            "boolean": {
              "type": "boolean"
            }
          }
        },
        {
          "type": "object",
          "required": [
            "integerToken"
          ],
          "additionalProperties": false,
          "properties": {
            "integerToken": {
              "type": "string",
              "pattern": "^-?(0|[1-9][0-9]*)(\\.[0-9]+)?([eE][+-]?[0-9]+)?$"
            }
          }
        },
        {
          "type": "object",
          "required": [
            "decimalToken"
          ],
          "additionalProperties": false,
          "properties": {
            "decimalToken": {
              "type": "string",
              "pattern": "^-?(0|[1-9][0-9]*)(\\.[0-9]+)?([eE][+-]?[0-9]+)?$"
            }
          }
        },
        {
          "type": "object",
          "required": [
            "string"
          ],
          "additionalProperties": false,
          "properties": {
            "string": {
              "type": "string"
            }
          }
        },
        {
          "type": "object",
          "required": [
            "binaryHex"
          ],
          "additionalProperties": false,
          "properties": {
            "binaryHex": {
              "type": "string",
              "pattern": "^([0-9a-fA-F]{2})*$"
            }
          }
        }
      ]
    },
    "compactKey": {
      "type": "object",
      "required": [
        "operation",
        "version",
        "profile",
        "sourceRef",
        "identity",
        "values",
        "keyPath",
        "bytesHex"
      ],
      "additionalProperties": false,
      "properties": {
        "operation": {
          "const": "encode-core-key-tuple"
        },
        "version": {
          "const": "3.0.0"
        },
        "profile": {
          "const": "umf-key-tuple-v1"
        },
        "identity": {
          "$ref": "#/$defs/keyIdentity"
        },
        "values": {
          "type": "array",
          "minItems": 1,
          "items": {
            "$ref": "#/$defs/keyValue"
          }
        },
        "keyPath": {
          "type": "string",
          "pattern": "^/modules/[0-9]+/elements/[0-9]+/keys/[0-9]+$"
        },
        "bytesHex": {
          "type": "string",
          "pattern": "^554d464b31([0-9a-f]{2})+$",
          "maxLength": 8000000
        },
        "sourceRef": {
          "const": "#/source"
        }
      },
      "description": "Structural receipt validation is insufficient: verification recomputes exact tuple bytes from retained candidate source/values and checks current document context. This establishes neither authorship nor native enforcement."
    }
  }
}
